module.exports = function (RED) {
    "use strict";

    function FilterNode(n) {
        RED.nodes.createNode(this, n);
        let node = this;

        // 配置过滤条件
        this.filterType = n.filterType; // location 或 time
        this.locationOperator = n.locationOperator || "not in"; // 位置操作符
        this.targetLocation = n.targetLocation || ""; // 目标位置
        this.timeOperator = n.timeOperator || "before"; // 时间操作符
        this.targetTime = n.targetTime || ""; // 目标时间

        // 当接收到输入消息时
        this.on("input", function (msg, send, done) {
            // 基于位置的过滤
            if (this.filterType === "location") {
                // 如果设置了位置过滤，进行条件判断
                if (this.locationOperator === "not in") {
                    // 如果目标位置不在指定范围内，则过滤掉该消息
                    if (msg.location && msg.location === this.targetLocation) {
                        return; // 不符合条件，丢弃消息
                    }
                } else if (this.locationOperator === "in") {
                    // 如果目标位置在指定范围内，则继续处理
                    if (msg.location !== this.targetLocation) {
                        return; // 不符合条件，丢弃消息
                    }
                }
            }

            // 基于时间的过滤
            if (this.filterType === "time") {
                let current = new Date(); // 当前时间
                
                // 将 targetTime（格式如 "14:30:00"）构造为今天的时间
                if (!this.targetTime) return;

                let [hours, minutes, seconds] = this.targetTime.split(":").map(Number);
                let target = new Date();
                target.setHours(hours, minutes, seconds || 0, 0); // 设置为今天的这个时间点

                if (this.timeOperator === "before" && current >= target) {
                    return; // 当前时间不在目标时间之前，丢弃
                } else if (this.timeOperator === "after" && current <= target) {
                    return; // 当前时间不在目标时间之后，丢弃
                }
            }

            // 如果消息符合过滤条件，传递给下游节点
            send(msg);
            done();
        });
    }

    // 注册 Filter 节点类型
    RED.nodes.registerType("Filter", FilterNode);
};
